{"policy":"permit (
    principal is User,
    action == Action::"modifyCloudResource",
    resource is CloudResource
)
when {
    principal.roles.containsAny([Role::"owner", Role::"developer", Role::"operator"])
};

forbid (
    principal is User,
    action == Action::"modifyCloudResource",
    resource is CloudResource
)
when {
    principal.roles.containsAny([Role::"owner", Role::"developer", Role::"operator"]) &&
    !context.mfaUsed
};

forbid (
    principal is User,
    action == Action::"modifyCloudResource",
    resource is CloudResource
)
when {
    principal.roles.containsAny([Role::"owner", Role::"developer", Role::"operator"]) &&
    resource.environment == Environment::"production" &&
    !resource.promoted &&
    !(principal.orgMembership in resource.orgUnit)
};"}
